values ('dialogu-kosove-serbi', date '1999-06-01', 'month', 'Qershor 1999', 'Baza',
        'Lufta përfundon dhe hyn në fuqi Rezoluta 1244', 'Pas fushatës ajrore të NATO-s, forcat serbe tërhiqen nga Kosova. Këshilli i Sigurimit miraton Rezolutën 1244, që vendos administrim ndërkombëtar dhe një prani ushtarake të udhëhequr nga NATO.', 'Është teksti që Beogradi citon ende sot kur kundërshton vendimet e Prishtinës, dhe baza ligjore e pranisë së KFOR-it.', 'draft', 'hand-written (pre-pipeline)', 'lufta-perfundon-dhe-hyn-ne-fuqi-rezoluta-1244')
on conflict (topic_slug, dedupe_key) do nothing;

