values ('dialogu-kosove-serbi', date '2020-09-04', 'day', '4 shtator 2020', 'Uashington',
        'Marrëveshjet e Uashingtonit', 'Në Shtëpinë e Bardhë, Kosova dhe Serbia nënshkruajnë veçmas dy dokumente pothuajse identike për normalizim ekonomik: autostrada dhe hekurudha lidhëse, njohje reciproke e diplomave, pjesëmarrje në mini-Schengenin rajonal dhe bashkëpunim energjetik. Dokumentet përmbajnë edhe pika që nuk kanë lidhje me njera-tjetrën, si zhvendosja e ambasadave në Jerusalem.', 'Shënoi hyrjen e Uashingtonit si tavolinë paralele me Brukselin, jo gjithnjë me të njëjtin drejtim.', 'draft', 'hand-written (pre-pipeline)', 'marreveshjet-e-uashingtonit')
