values ('dialogu-kosove-serbi', date '2022-08-01', 'month', 'Gusht–nëntor 2022', 'Targat',
        'Kriza e targave rikthehet dhe serbët dalin nga institucionet', 'Afati për riregjistrimin e automjeteve me targa serbe sjell barrikada të reja në veri dhe ndërhyrje të KFOR-it në rrugët kryesore. Në nëntor, rreth gjashtëqind zyrtarë serbë — policë, gjyqtarë, prokurorë dhe anëtarë të kuvendeve komunale — japin dorëheqje të njehkohshme, duke lënë katër komuna pa administratë funksionale.', 'Dorëheqjet krijuan zbrazëtinë institucionale që çoi te zgjedhjet e kontestuara të vitit 2023.', 'draft', 'hand-written (pre-pipeline)', 'kriza-e-targave-rikthehet-dhe-serbet-dalin-nga-institucionet')
