insert into public.dosje_milestones
       (topic_slug, event_date, date_precision, display_date, tag, title, summary, why, status, drafted_by, dedupe_key)
values ('kfor', date '1999-06-01', 'month', 'Qershor 1999', 'Mandati',
        'KFOR-i vendoset në Kosovë', 'Pas fushatës ajrore të NATO-s dhe tërheqjes së forcave serbe, Këshilli i Sigurimit miraton Rezolutën 1244 dhe autorizon një prani ndërkombëtare sigurie. Rreth 50 mijë trupa nga më shumë se tridhjetë shtete hyjnë në Kosovë, të ndarë në pesë zona përgjegjësie. Detyra e parë është ndalja e armiqesive, çarmatimi i formacioneve të armatosura dhe kthimi i qindra mijë njerezve të zhvendosur. Nga ky moment siguria në Kosovë nuk është më çështje e Beogradit.', 'Mandati i vitit 1999 është ende baza ligjore e pranisë së KFOR-it sot, pavarësisht ndryshimit të madh të kontekstit.', 'draft', 'hand-written (pre-pipeline)', 'kfor-i-vendoset-ne-kosove')
