insert into public.dosje_milestones
       (topic_slug, event_date, date_precision, display_date, tag, title, summary, why, status, drafted_by, dedupe_key)
values ('kfor', date '2008-02-01', 'month', 'Shkurt 2008', 'Statusi',
        'KFOR-i mbetet pas shpalljes së pavarësisë', 'Me shpalljen e pavarësisë, NATO konfirmon se KFOR-i qendron dhe se baza e mandatit mbetet Rezoluta 1244, jo ftesa e një shteti të ri. Kjo zgjedhje mban brenda aleancës edhe shtetet që nuk e njohin Kosovën, sepse asnjëra nuk detyrohet të ndryshojë qendrim për të mbajtur trupat në terren. Prandaj KFOR-i nuk është forcë e Kosovës, nuk merr urdhëra nga Prishtina dhe raporton në Bruksel.', 'Prandaj KFOR-i nuk është forcë e Kosovës dhe nuk merr urdhera nga Prishtina.', 'draft', 'hand-written (pre-pipeline)', 'kfor-i-mbetet-pas-shpalljes-se-pavaresise')
on conflict (topic_slug, dedupe_key) do nothing;

insert into public.dosje_milestones
       (topic_slug, event_date, date_precision, display_date, tag, title, summary, why, status, drafted_by, dedupe_key)
values ('kfor', date '2013-01-01', 'year', '2013', 'Zvogëlimi',
        'Forca zvogëlohet në rreth pesë mijë trupa', 'Pas disa vitesh me përmirësim të gjendjes, NATO kalon nga një prani e madhe e përhershme në një forcë të vogël me rezerva të vendosura jashtë vendit. Numri bie në rreth pesë mijë trupa dhe shumë baza dorëzohen. Modeli mbeshtetet te supozimi se përforcimet mund të mbërrijnë brenda ditesh, gjë që do të testohet seriozisht një dekadë më vonë.', 'Zvogëlimi shpjegon pse çdo krizë e mëvonshme kërkon dërgim të shpejtë forcash shtesë nga jashtë.', 'draft', 'hand-written (pre-pipeline)', 'forca-zvogelohet-ne-rreth-pese-mije-trupa')
on conflict (topic_slug, dedupe_key) do nothing;

insert into public.dosje_milestones
       (topic_slug, event_date, date_precision, display_date, tag, title, summary, why, status, drafted_by, dedupe_key)
values ('kfor', date '2023-05-29', 'day', '29 maj 2023', 'Përplasje',
        'Ushtarë të KFOR-it lëndohen në veri', 'Pas zgjedhjeve lokale me pjesëmarrje nën tre për qind, kryetarët e rinj hyjnë në godinat komunale të veriut me shoqërim policor. Protestat përshkallezohen para komunës së Zveçanit dhe dhjetëra ushtarë italianë e hungarezë të KFOR-it lëndohen, disa rëndësisht. NATO dërgon menjëherë rreth pesëqind trupa shtesë, ndersa BE-ja vendos masa ndaj Prishtinës për mënyrën si u veprua.', 'Ishte hera e parë pas shumë vitesh që trupat e NATO-s pësuan lëndime të shumta në Kosovë.', 'draft', 'hand-written (pre-pipeline)', 'ushtare-te-kfor-it-lendohen-ne-veri')
on conflict (topic_slug, dedupe_key) do nothing;

